{
  "command": "dbxnb-dbx_run_sql --sql \"CREATE OR REPLACE TABLE workspace.exam_xa6d3d.m1_top_zips AS WITH zip_stats AS (SELECT pickup_zip, COUNT(*) AS trips, SUM(fare_amount) AS total_fare_raw FROM samples.nyctaxi.trips WHERE pickup_zip IS NOT NULL GROUP BY pickup_zip HAVING COUNT(*) >= 200), busiest_hour_cte AS (SELECT pickup_zip, hour(tpep_pickup_datetime) AS hour_of_day, COUNT(*) AS cnt, ROW_NUMBER() OVER (PARTITION BY pickup_zip ORDER BY COUNT(*) DESC, hour(tpep_pickup_datetime) ASC) AS rn FROM samples.nyctaxi.trips WHERE pickup_zip IS NOT NULL GROUP BY pickup_zip, hour(tpep_pickup_datetime)), busiest AS (SELECT pickup_zip, hour_of_day AS busiest_hour FROM busiest_hour_cte WHERE rn = 1), total_rev AS (SELECT SUM(total_fare_raw) AS grand_total FROM zip_stats), ranked AS (SELECT z.pickup_zip, z.trips, ROUND(z.total_fare_raw,2) AS total_fare, DENSE_RANK() OVER (ORDER BY z.total_fare_raw DESC) AS fare_rank, ROUND(SUM(z.total_fare_raw) OVER (ORDER BY z.total_fare_raw DESC, z.pickup_zip ASC) / t.grand_total * 100,2) AS cumulative_share_pct, b.busiest_hour FROM zip_stats z JOIN busiest b ON z.pickup_zip = b.pickup_zip CROSS JOIN total_rev t) SELECT pickup_zip, trips, total_fare, fare_rank, cumulative_share_pct, busiest_hour FROM ranked WHERE fare_rank <= 10 ORDER BY fare_rank;\"",
  "description": "Create top zip table",
  "mode": "sync",
  "initial_wait": 120
}

